function i(t){return t?`¥${(t/100).toFixed(2)}`:"免费"}function a(t){if(!t)return"-";const e=new Date(t*1e3),n=r=>String(r).padStart(2,"0");return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())} ${n(e.getHours())}:${n(e.getMinutes())}`}function o(t){if(!t)return"-";const e=new Date(t*1e3),n=r=>String(r).padStart(2,"0");return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())}`}function u(t){if(!t)return"-";const e=["B","KB","MB","GB"];let n=0,r=t;for(;r>=1024&&n<e.length-1;)r/=1024,n+=1;return`${r.toFixed(n?1:0)} ${e[n]}`}function f(t){if(!t)return"0:00";const e=Math.floor(t/60),n=t%60;return`${e}:${String(n).padStart(2,"0")}`}export{f as a,o as b,a as d,u as f,i as m};
